import {aliases,seeds} from './catalog.js';
const IA='https://archive.org';
const COMMONS='https://commons.wikimedia.org/w/api.php';
export const plain=value=>String(Array.isArray(value)?value.join(', '):value??'').replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim();
export const norm=s=>plain(s).toLocaleLowerCase('ru').replace(/ё/g,'е');
const arr=x=>Array.isArray(x)?x:x?[x]:[];
export function safeURL(value,hosts){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))return '';if(hosts&&!hosts.some(h=>u.hostname===h||u.hostname.endsWith('.'+h)))return '';u.protocol='https:';return u.href}catch{return ''}}
export function licenseURL(value){return arr(value).map(x=>safeURL(x,['creativecommons.org','creativecommons.org.uk'])).find(Boolean)||'';}
export function licenseName(url){if(/publicdomain|\/zero\//.test(url))return 'Public Domain';const m=url.match(/licenses\/([^/]+)\/([^/]+)/);return m?'CC '+m[1].toUpperCase()+' '+m[2]:'Лицензия источника';}
export async function getJSON(url,signal,timeout=18000){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),timeout);const stop=()=>ctrl.abort();signal?.addEventListener('abort',stop,{once:true});if(signal?.aborted)ctrl.abort();try{const r=await fetch(url,{signal:ctrl.signal});if(!r.ok)throw new Error(r.status===429?'Источник временно ограничил запросы. Попробуйте немного позже.':'Источник не ответил ('+r.status+').');const data=await r.json();if(data.error)throw new Error('Источник временно не ответил. Повторите поиск.');return data}finally{clearTimeout(timer);signal?.removeEventListener('abort',stop)}}
function params(obj){const p=new URLSearchParams();for(const [k,v] of Object.entries(obj))for(const t of arr(v))p.append(k,t);return p.toString()}
const quote=s=>'"'+String(s).replace(/["\\:+\-!(){}\[\]^~*?<>|&]/g,' ').slice(0,150).trim()+'"';
const openQuery='(licenseurl:*publicdomain* OR licenseurl:*by*)';
const collectionQuery='(collection:feature_films OR collection:animationandcartoons OR collection:classic_tv)';
export function classify(record){const t=norm([record.title,record.subject,arr(record.collection).filter(x=>!String(x).startsWith('fav-')),record.categories].flat().join(' '));const animated=/animat|cartoon|мульт|popeye|betty boop|superman|looney|merrie melodies/.test(t);const series=/classic_tv|\btv\b|television|series|season|s\d{1,2}e\d|episodes|сериал|sherlockholmes1954|bonanza|popeye|betty boop|superman|looney|merrie melodies/.test(t);return animated?(series?'animatedSeries':'animation'):(series?'series':'film')}
export function fromArchive(d){const seed=seeds.find(s=>s.ref===d.identifier);if(seed)return {...seed,license:licenseURL(d.licenseurl)};const license=licenseURL(d.licenseurl);if(!d.identifier||!license)return null;return {id:'ia:'+d.identifier,ref:d.identifier,provider:'archive',title:plain(d.title)||d.identifier,original:plain(d.title),kind:classify(d),year:plain(d.year||d.date).match(/\d{4}/)?.[0]||'',description:plain(d.description).slice(0,1600),creator:plain(d.creator),language:plain(d.language)||'Не указан',poster:IA+'/services/img/'+encodeURIComponent(d.identifier),license,source:IA+'/details/'+encodeURIComponent(d.identifier)}}
export async function translatedTitle(q,signal){const key=norm(q);if(aliases[key])return aliases[key];if(/^(киберпанк|cyberpunk)(?:[:\s]|$)/i.test(q)&&!/2077/.test(q))return 'Cyberpunk Edgerunners';if(!/[а-яё]/i.test(q)||q.length<3)return '';try{const j=await getJSON('https://ru.wikipedia.org/w/api.php?'+params({action:'query',format:'json',origin:'*',generator:'search',gsrsearch:q,gsrnamespace:0,gsrlimit:1,prop:'langlinks',lllang:'en'}),signal,5000);const page=Object.values(j.query?.pages||{})[0];return page?.langlinks?.[0]?.['*']?.replace(/\s*\([^)]*\)\s*/g,'').trim()||''}catch{return ''}}
export async function searchArchive({q='',translated='',kind='all',page=1,sort='relevance',signal}){const terms=[q,translated].filter(Boolean);let text=terms.length?'('+terms.map(t=>'title:('+t.split(/\s+/).filter(Boolean).map(quote).join(' AND ')+')').join(' OR ')+')':'';let filter='';if(kind==='film')filter=' AND NOT (collection:animationandcartoons OR collection:classic_tv)';if(kind==='animation')filter=' AND (collection:animationandcartoons OR subject:animation OR subject:cartoon) AND NOT (title:Popeye OR title:Superman OR title:"Betty Boop")';if(kind==='series')filter=' AND collection:classic_tv';if(kind==='animatedSeries')filter=' AND (title:Popeye OR title:Superman OR title:"Betty Boop" OR title:"Looney Tunes" OR subject:"animated series")';const query=['mediatype:movies',openQuery,collectionQuery,text].filter(Boolean).join(' AND ')+filter;const j=await getJSON(IA+'/advancedsearch.php?'+params({q:query,'fl[]':['identifier','title','year','date','description','licenseurl','subject','creator','collection','language'],'rows':24,page,output:'json','sort[]':sort==='new'?'year desc':sort==='old'?'year asc':text?undefined:'downloads desc'}),signal);if(!j.response)throw new Error('Не удалось прочитать ответ Internet Archive.');return {items:j.response.docs.map(fromArchive).filter(Boolean),total:j.response.numFound,page};}
function commonsItem(p){const vi=p.videoinfo?.[0];if(!vi||vi.duration<240)return null;const em=vi.extmetadata||{},license=licenseURL(em.LicenseUrl?.value);const pd=/public domain|cc0/i.test(em.LicenseShortName?.value||'');if(!license&&!pd)return null;const seed=seeds.find(s=>s.commons===p.title);const title=plain(em.ObjectName?.value||p.title.replace(/^File:/,'').replace(/\.(webm|ogv|mp4)$/i,''));return {...(seed||{}),id:'wc:'+p.pageid,ref:p.title,provider:'commons',title:seed?.title||title,original:title,kind:seed?.kind||classify({title,categories:em.Categories?.value}),year:seed?.year||plain(em.DateTimeOriginal?.value).match(/(?:18|19|20)\d{2}/)?.[0]||'',duration:vi.duration,description:seed?.description||plain(em.ImageDescription?.value).slice(0,1500),creator:plain(em.Artist?.value||em.Credit?.value),poster:safeURL(vi.thumburl,['wikimedia.org'])||'assets/cover.svg',license:license||'https://creativecommons.org/publicdomain/mark/1.0/',source:safeURL(vi.descriptionurl,['wikimedia.org']),videoInfo:vi}}
export async function searchCommons({q='',translated='',kind='all',page=1,signal}){const term=translated||q||({all:'"complete film"',film:'"silent film"',animation:'"animated film"',series:'"television episode"',animatedSeries:'"Popeye"'}[kind]);const j=await getJSON(COMMONS+'?'+params({action:'query',format:'json',origin:'*',generator:'search',gsrsearch:(q?'intitle:"'+term.replace(/["\\]/g,' ')+'"':term)+' filetype:video -intitle:trailer -intitle:excerpt -intitle:teaser',gsrnamespace:6,gsrlimit:8,gsroffset:(page-1)*8,prop:'videoinfo',viprop:'url|size|derivatives|extmetadata',viextmetadatafilter:'ObjectName|ImageDescription|Artist|LicenseShortName|LicenseUrl|DateTimeOriginal|Categories',viurlwidth:400}),signal);return {items:Object.values(j.query?.pages||{}).sort((a,b)=>a.index-b.index).map(commonsItem).filter(Boolean),more:!!j.continue,page};}
const videoExt=/\.(mp4|m4v|webm)$/i;
export function archiveEpisodes(data,item){if(data.is_dark||data.metadata?.access_restricted||String(data.metadata?.['is_restricted'])==='true')throw new Error('Источник ограничил просмотр этой записи.');const license=licenseURL(data.metadata?.licenseurl);if(!license)throw new Error('Источник не указал открытую лицензию для видео.');const all=data.files||[];const byName=new Map(all.map(f=>[f.name,f]));const files=all.filter(f=>videoExt.test(f.name)&&!f.private&&Number(f.size)>1000000&&!/trailer|teaser|preview|sample|DVD_NTSC[1-9]/i.test(f.name));const episodic=['series','animatedSeries'].includes(item.kind);const longest=Math.max(0,...files.map(f=>Number(f.length)||0));const selected=episodic?files:files.filter(f=>!longest||!Number(f.length)||Number(f.length)>longest*.96);const root=f=>{let r=f;for(let i=0;i<8&&r.original&&byName.has(r.original);i++)r=byName.get(r.original);return r.name.replace(/\.[^.]+$/,'').replace(/[_ .-](512kb|\d{3,4}p|h264|h\.264|vp9).*$/i,'')};const groups=new Map();for(const f of selected){const key=episodic?root(f):'film';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(f)}
const episodes=[...groups.entries()].map(([key,fs],idx)=>{const seen=new Set();const sources=fs.sort((a,b)=>(Number(b.height)||0)-(Number(a.height)||0)||(/surround/i.test(a.name)?1:-1)).map(f=>({url:IA+'/download/'+encodeURIComponent(item.ref)+'/'+f.name.split('/').map(encodeURIComponent).join('/'),height:Number(f.height)||0,width:Number(f.width)||0,type:/webm$/i.test(f.name)?'video/webm':'video/mp4',label:Number(f.height)?f.height+'p':/512kb/i.test(f.name)?'Экономия · MP4':'Оригинал · '+(/webm$/i.test(f.name)?'WebM':'MP4'),duration:Number(f.length)||0,provider:'Internet Archive',size:Number(f.size)})).filter(s=>{const key=s.height+':'+s.type;if(seen.has(key))return false;seen.add(key);return true});return {id:key,title:episodic?key.replace(/[_]/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2'):item.title,duration:sources[0]?.duration||item.duration||0,sources}}).filter(e=>e.sources.length).sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}));if(!episodes.length)throw new Error('У этой записи нет доступного видео в MP4 или WebM.');return {episodes,license,creator:plain(data.metadata?.creator)||item.creator||'Автор указан на странице источника',description:item.description||plain(data.metadata?.description),source:IA+'/details/'+encodeURIComponent(item.ref),language:plain(data.metadata?.language)||'Оригинальная звуковая дорожка'};}
export async function resolveArchive(item,signal){return archiveEpisodes(await getJSON(IA+'/metadata/'+encodeURIComponent(item.ref),signal,22000),item)}
function commonsSources(vi){const derivatives=vi.derivatives||[];const seen=new Set();return derivatives.filter(d=>/video\/webm|video\/mp4/.test(d.type)&&!/audio\//.test(d.type)).sort((a,b)=>b.height-a.height||(/vp9/.test(a.type)?-1:1)).map(d=>({url:safeURL(d.src,['wikimedia.org']),height:d.height,width:d.width,type:d.type,label:d.height+'p',provider:'Wikimedia Commons',duration:vi.duration})).filter(s=>{if(!s.url||seen.has(s.height))return false;seen.add(s.height);return true})}
export async function resolveCommons(item,signal){let vi=item.videoInfo;if(!vi){const j=await getJSON(COMMONS+'?'+params({action:'query',format:'json',origin:'*',titles:item.ref,prop:'videoinfo',viprop:'url|size|derivatives|extmetadata',viextmetadatafilter:'Artist|LicenseUrl|LicenseShortName|ImageDescription',viurlwidth:640}),signal);vi=Object.values(j.query?.pages||{})[0]?.videoinfo?.[0]}if(!vi)throw new Error('Видео не найдено в Wikimedia Commons.');const license=licenseURL(vi.extmetadata?.LicenseUrl?.value)||item.license;if(!license)throw new Error('Не удалось получить лицензию видео.');const sources=commonsSources(vi);if(!sources.length)throw new Error('Источник не предлагает поддерживаемый видеоформат.');return {episodes:[{id:item.ref,title:item.title,duration:vi.duration,sources}],license,creator:plain(vi.extmetadata?.Artist?.value)||item.creator,source:safeURL(vi.descriptionurl,['wikimedia.org'])||item.source,language:'Оригинальная звуковая дорожка'};}
export async function resolveItem(item,signal){
 if(item.provider==='commons')return resolveCommons(item,signal);
 if(!item.commons)return resolveArchive(item,signal);
 const result=await Promise.allSettled([resolveArchive(item,signal),resolveCommons({...item,ref:item.commons,videoInfo:undefined},signal)]);
 const available=result.filter(r=>r.status==='fulfilled').map(r=>r.value);
 if(!available.length)throw result[0].reason;
 const data=available[0];
 if(available.length>1&&Math.abs(available[0].episodes[0].duration-available[1].episodes[0].duration)<3){data.episodes[0].sources.push(...available[1].episodes[0].sources);data.alternateSource=available[1].source;}
 return data;
}
